111	Lemma has_left_child_psi :
112	  forall (j i : nat) (w : seq nat),
113	  uniq w ->
114	  has_left_child i (psi j w) = has_left_child i w.
115	Proof.
116	suff Hgen : forall n j i w, size w <= n ->
117	  uniq w -> has_left_child i (psi j w) = has_left_child i w.
118	  by move=> j i w Hu; apply: (Hgen (size w));
119	     rewrite ?leqnn.
120	elim=> [|n IH] j i w Hsz Huniq.
121	  by move: Hsz; rewrite leqn0 => /eqP/size0nil ->.
122	have [Htriv | Hws_gt1] := leqP (window_size j w) 1.
123	  by rewrite (psi_id_trivial Htriv).
124	have Hjw := ws_lt_size Hws_gt1.
125	have Hw_ne : w <> [::] by case: (w) Hjw.
126	case: (w) Hw_ne Huniq Hws_gt1 Hjw Hsz =>
127	  [//|a s0] _ Huniq Hws_gt1 Hjw Hsz.
128	set s := a :: s0.
129	set m := mm_pos s.
130	have Hm : m < size s by apply: mm_pos_lt.
131	have Hs_ne : s <> [::] by discriminate.
132	have Hm' : mm_pos (psi j s) = m by apply: mm_pos_psi_eq.
133	have Hpsi_ne : psi j s <> [::].
134	  by move=> E; move: Hjw; rewrite -(size_psi j) E.
135	have [a' [s0' Hpsi_eq]] : exists a' s0', psi j s =
136	  a' :: s0'.
137	  by case: (psi j s) Hpsi_ne => [//|x y] _; exists x, y.
138	have Hm'c : mm_pos (a' :: s0') = m
139	  by rewrite -Hpsi_eq.
140	rewrite Hpsi_eq (has_left_child_cons i a' s0') Hm'c.
141	rewrite (has_left_child_cons i a s0) -/m.
142	case: (ltngtP i m) => [Him | Hmi | Hieqm].
143	- (* i < m *)
144	  case: (ltngtP j m) => [Hjm | Hmj | Hjeqm].
145	  + (* j < m *)
146	    abstract (
147	    rewrite -Hpsi_eq
148	      (take_mm_psi Hs_ne Huniq Hws_gt1 Hjm);
149	    apply: IH;
150	    [ rewrite size_take Hm;
151	      exact: leq_trans (ltnW Hm) Hsz
152	    | have : uniq (take m s ++ drop m s)
153	        by rewrite cat_take_drop;
154	      by rewrite cat_uniq => /andP [? /andP [? ?]] ]).
155	  + abstract
156	      (by rewrite -Hpsi_eq
157	         (@take_psi m j s (ltnW Hmj))).
158	  + abstract
159	      (by rewrite -Hpsi_eq Hjeqm
160	         (@take_psi m m s (leqnn m))).
161	- (* i > m *)
162	  case: (ltngtP j m) => [Hjm | Hmj | Hjeqm].
163	  + (* j < m *)
164	    abstract (
165	    suff -> : drop m.+1 (a' :: s0') =
166	      drop m.+1 (a :: s0) by [];
167	    rewrite -Hpsi_eq;
168	    apply: drop_psi_above;
169	    apply: leq_trans (window_fits_left Hs_ne Hjm) _;
170	    exact: leqnSn).
171	  + (* j > m *)
172	    abstract (
173	    suff -> : drop m.+1 (a' :: s0') =
174	      psi (j - m - 1) (drop m.+1 (a :: s0));
175	    [ apply: IH;
176	      [ rewrite /s /= size_drop;
177	        exact: leq_trans (leq_subr _ _) (ltnW Hsz)
178	      | have : uniq (take m.+1 s ++ drop m.+1 s)
179	          by rewrite cat_take_drop;
180	        by rewrite cat_uniq => /andP [_ /andP [_ ?]] ]
181	    | by rewrite -Hpsi_eq
182	         (drop_mm_psi Hs_ne Huniq Hws_gt1 Hmj) ]).
183	  + (* j = m: use has_left_child_order_iso *)
184	    abstract (
185	    subst j;
186	    have Hws_m : window_size m s = size s - m
187	      by rewrite (window_size_cons m a s0) -/m ltnn eqxx;
188	    have Hws_drop : 1 < size (drop m s)
189	      by rewrite size_drop -Hws_m;
190	    have Hdm_ne : drop m s <> [::]
191	      by case: (drop m s) Hws_drop;
192	    have Huniq_dm : uniq (drop m s)
193	      by (have : uniq (take m s ++ drop m s)
194	        by rewrite cat_take_drop);
195	      rewrite cat_uniq => /andP [_ /andP [_ ?]];
196	    have Hmm_drop : mm_pos (drop m s) = 0
197	      by exact: mm_pos_drop_mm;
198	    have Hpsi_m_eq : psi m s =
199	      take m s ++ rank_shift_seq (drop m s)
200	      by (rewrite /psi;
201	      have Hwa_m : window_at m s = drop m s
202	        by rewrite (window_at_cons m a s0)
203	           -/m ltnn eqxx //;
204	      rewrite Hwa_m Hws_m;
205	      by rewrite subnKC ?drop_size ?cats0 // ltnW);
206	    have Him' : 0 < i - m by rewrite subn_gt0;
207	    have Hdrop_psi : drop m.+1 (a' :: s0') =
208	      behead (rank_shift_seq (drop m s))
209	      by (rewrite -Hpsi_eq Hpsi_m_eq;
210	      rewrite drop_cat size_take Hm;
211	      have -> : m.+1 < m = false
212	        by rewrite ltnNge leqnSn;
213	      by rewrite /= subSn // subnn drop0);
214	    have Hdrop_orig : drop m.+1 (a :: s0) =
215	      behead (drop m s)
216	      by rewrite /s /= drop0;
217	    rewrite Hdrop_psi Hdrop_orig;
218	    apply: has_left_child_order_iso;
219	    [ by rewrite !size_behead size_rank_shift_seq2
220	    | apply: (subseq_uniq (suffix_subseq 1 _));
221	      by rewrite (perm_uniq (rank_shift_perm_eq _))
222	    | exact: (subseq_uniq (suffix_subseq 1 _))
223	    | move=> p q Hp Hq;
224	      have Hsz_bh : size (behead (drop m s)) =
225	        (size (drop m s)).-1
226	        by rewrite size_behead;
227	      have Hp1 : p.+1 < size (drop m s)
228	        by rewrite -ltnS prednK //;
229	           rewrite Hsz_bh in Hp; apply: ltnW;
230	      have Hq1 : q.+1 < size (drop m s)
231	        by rewrite -ltnS prednK //;
232	           rewrite Hsz_bh in Hq; apply: ltnW;
233	      rewrite -[behead (rank_shift_seq _)]
234	        (drop1 (rank_shift_seq (drop m s)));
235	      rewrite -[behead (drop m s)]
236	        (drop1 (drop m s));
237	      rewrite !nth_drop;
238	      rewrite [1 + p]addnC [1 + q]addnC;
239	      have Hrsz : size (rank_shift_seq (drop m s))
240	        = size (drop m s)
241	        by rewrite size_rank_shift_seq2;
242	      have Hp1' : p.+1 < size s
243	        by rewrite /s /= ltnS;
244	        rewrite size_drop /= in Hp1;
245	        apply: leq_trans (leq_subr _ _) (ltnW Hsz);
246	      have Hq1' : q.+1 < size s
247	        by rewrite /s /= ltnS;
248	        rewrite size_drop /= in Hq1;
249	        apply: leq_trans (leq_subr _ _) (ltnW Hsz);
250	      have Hhead_ext : (head 0 (drop m s) ==
251	        nth 0 (sort leq (drop m s)) 0) ||
252	        (head 0 (drop m s) == nth 0 (sort leq (drop m s))
253	        (size (drop m s)).-1)
254	        by apply: window_head_extremum => //;
255	        rewrite (window_size_cons m a s0)
256	          -/m ltnn eqxx //;
257	      symmetry;
258	      exact: rank_shift_preserves_interior_order
259	        Huniq_dm Hws_drop Hhead_ext
260	        (ltnW (ltn0Sn _)) (ltnW (ltn0Sn _))
261	        Hp1 Hq1 ]).
262	- (* i = m *)
263	  by [].
264	Qed.
