273	Lemma endpoint_implies_next_has_left_child :
274	  forall (k : nat) (w : seq nat),
275	    uniq w -> k.+1 < size w -> ~~ is_internal k w ->
276	    has_left_child k.+1 w.
277	Proof.
278	move=> k w; move: w k.
279	suff Hind : forall n k w, size w <= n ->
280	  uniq w -> k.+1 < size w -> ~~ is_internal k w ->
281	  has_left_child k.+1 w by move=> k w; apply: Hind.
282	elim => [|n IH]; first by move=> k [].
283	move=> k [//|a s0] Hsz Huniq Hk1 Hep.
284	set j := mm_pos (a :: s0).
285	have Hj : j < (size s0).+1 by apply: mm_pos_lt.
286	have Hk_lt : k < (size s0).+1 :=
287	  ltn_trans (ltnSn k) Hk1.
288	have Hws_k : window_size k (a :: s0) <= 1.
289	  move: Hep; rewrite /is_internal Hk_lt /=.
290	  by rewrite -leqNgt.
291	case: (ltngtP k j) => [Hkj | Hjk | Hkj].
292	- (* k < j *)
293	  case: (ltngtP k.+1 j) => [Hk1j | Hk1j | Hk1j].
294	  + abstract (
295	    rewrite (has_left_child_cons k.+1 a s0) /= -/j
296	      Hk1j;
297	    apply: IH;
298	    [ rewrite size_take Hj -ltnS;
299	      exact: leq_trans Hj Hsz
300	    | have : uniq (take j (a :: s0) ++
301	               drop j (a :: s0))
302	        by rewrite cat_take_drop;
303	      by rewrite cat_uniq => /andP [? _]
304	    | by rewrite size_take Hj
305	    | rewrite /is_internal size_take Hj Hkj /=;
306	      rewrite -leqNgt;
307	      have H := window_size_cons k a s0;
308	      rewrite /= -/j Hkj in H;
309	      by rewrite -H ]).
310	  + abstract
311	      (by rewrite ltnS in Hk1j;
312	       move: (leq_gtF Hk1j); rewrite Hkj).
313	  + abstract
314	      (rewrite (has_left_child_cons k.+1 a s0) /= -/j;
315	      by rewrite Hk1j ltnn eqxx -Hk1j).
316	- (* j < k *)
317	  abstract (
318	  have Hjk1 : j < k.+1 := ltn_trans Hjk (ltnSn k);
319	  rewrite (has_left_child_cons k.+1 a s0) /= -/j;
320	  have -> : k.+1 < j = false
321	    by apply/negbTE; rewrite -leqNgt ltnW;
322	  have -> : (k.+1 == j) = false by apply: gtn_eqF;
323	  have Hk1_shift : k.+1 - j - 1 = (k - j - 1).+1
324	    by rewrite -!addn1 -!addnBAC ?(ltnW Hjk);
325	  rewrite Hk1_shift;
326	  apply: IH;
327	  [ rewrite size_drop /= -ltnS;
328	    exact: leq_ltn_trans (leq_subr _ _) Hsz
329	  | move: Huniq;
330	    rewrite -{1}(cat_take_drop j.+1 (a :: s0))
331	      cat_uniq;
332	    by move=> /andP [_ /andP [_ ->]]
333	  | rewrite size_drop -Hk1_shift;
334	    exact: ltn_sub2r (ltnW Hjk1) Hk1
335	  | have Hk_dw : k - j - 1 <
336	      size (drop j.+1 (a :: s0))
337	      by apply: ltn_trans (ltnSn _);
338	      rewrite size_drop -Hk1_shift;
339	      exact: ltn_sub2r (ltnW Hjk1) Hk1;
340	    rewrite /is_internal Hk_dw /=;
341	    rewrite -leqNgt;
342	    have H := window_size_cons k a s0;
343	    rewrite /= -/j (ltn_eqF Hjk) in H;
344	    rewrite ifN in H;
345	      last by rewrite -leqNgt ltnW;
346	    by rewrite -H ]).
347	- (* k = j: impossible *)
348	  abstract (
349	  exfalso;
350	  have Hws_root := window_size_cons j a s0;
351	  rewrite /= -/j ltnn eqxx in Hws_root;
352	  have : 1 < (size s0).+1 - j
353	    by rewrite -Hkj ltn_subRL addnC /=;
354	       rewrite Hkj;
355	  by rewrite -Hws_root =>
356	     /(leq_ltn_trans Hws_k); rewrite ltnn).
357	Qed.
