368	Lemma window_size_last_fuel :
369	  forall fuel w, size w <= fuel -> 0 < size w ->
370	  window_size_fuel fuel (size w).-1 w = 1.
371	Proof.
372	elim=> [w Hsz Hne|fuel IH [|a s0] Hsz Hne] //.
373	  by move: Hsz Hne; case: w.
374	set s := a :: s0. set j := mm_pos s.
375	have Hj : j < size s by apply: mm_pos_lt.
376	have Hj2 : j <= size s0 by rewrite -ltnS.
377	rewrite /= -/s -/j.
378	have Hjn : (size s0 < j) = false
379	  by apply/negbTE; rewrite -leqNgt.
380	rewrite Hjn.
381	case Hjq: (size s0 == j).
382	  abstract (by move/eqP: Hjq => <-;
383	     rewrite /s /= subSn // subnn).
384	abstract (
385	have Hjl : j < size s0
386	  by rewrite ltn_neqAle eq_sym Hjq /=
387	     leqNgt Hjn;
388	change (window_size_fuel fuel
389	  (size s0 - j - 1) (drop j s0) = 1);
390	have Hsz_ds : size (drop j s0) = size s0 - j
391	  by rewrite size_drop;
392	have H0ds : 0 < size (drop j s0)
393	  by rewrite Hsz_ds subn_gt0;
394	have Hfuel_ok : size (drop j s0) <= fuel
395	  by rewrite Hsz_ds;
396	  apply: leq_trans (leq_subr _ _) _;
397	  rewrite ltnS in Hsz;
398	have -> : size s0 - j - 1 =
399	  (size (drop j s0)).-1
400	  by rewrite Hsz_ds subn1;
401	exact: IH Hfuel_ok H0ds).
402	Qed.
403	
404	Lemma window_size_last w :
405	  0 < size w ->
406	  window_size (size w).-1 w = 1.
407	Proof.
408	move=> Hne; rewrite /window_size.
409	exact: window_size_last_fuel (leqnn _) Hne.
410	Qed.
