412	Lemma LR_pred_is_endpoint :
413	  forall (i : nat) (w : seq nat),
414	  uniq w -> 0 < i -> is_internal i w ->
415	  has_left_child i w ->
416	  ~~ is_internal i.-1 w.
417	Proof.
418	suff H : forall n i w, size w <= n ->
419	  uniq w -> 0 < i -> is_internal i w ->
420	  has_left_child i w ->
421	  ~~ is_internal i.-1 w.
422	  by move=> i w; exact: H (leqnn _).
423	elim=> [i w Hsz _ _ Hint _|
424	  n IH i [|a s0] Hsz Huniq Hi0 Hint Hlc] //.
425	  move: Hint; rewrite /is_internal =>
426	    /andP [Hi _].
427	  by move: (leq_trans Hi Hsz); rewrite ltn0.
428	set s := a :: s0. set j := mm_pos s.
429	have Hj : j < size s by apply: mm_pos_lt.
430	have Hj2 : j <= size s0 by rewrite -ltnS.
431	have Hiw : i < size s
432	  by move: Hint; rewrite /is_internal =>
433	     /andP [].
434	have Hws : 1 < window_size i s
435	  by move: Hint; rewrite /is_internal =>
436	     /andP [].
437	rewrite has_left_child_cons -/s -/j in Hlc.
438	rewrite window_size_cons -/s -/j in Hws.
439	case: (ltngtP i j) => [Hij | Hji | Heq].
440	- (* i < j: both i and i-1 in left subtree *)
441	  abstract (
442	  rewrite Hij in Hlc Hws;
443	  have Hi1j : i.-1 < j
444	    by exact:
445	       leq_ltn_trans (leq_pred _) Hij;
446	  rewrite /is_internal window_size_cons
447	    -/s -/j Hi1j;
448	  have Htake_sz : size (take j s) = j
449	    by rewrite size_take Hj;
450	  have Huniq_t : uniq (take j s)
451	    by exact:
452	       subseq_uniq (take_subseq _ _) Huniq;
453	  case E:
454	    (1 < window_size i.-1 (take j s));
455	    last by rewrite andbF;
456	  have Hint_t : is_internal i (take j s)
457	    by rewrite /is_internal Htake_sz Hij Hws;
458	  have Hsz_t : size (take j s) <= n
459	    by rewrite Htake_sz;
460	    apply: leq_trans Hj2 _;
461	    rewrite /s /= ltnS in Hsz;
462	  have := IH i (take j s) Hsz_t Huniq_t
463	    Hi0 Hint_t Hlc;
464	  by rewrite /is_internal
465	     Htake_sz Hi1j /= E).
466	- (* j < i: right subtree *)
467	  abstract (
468	  have Hlti : ~~ (i < j)
469	    by rewrite -leqNgt ltnW;
470	  have Hi_ne_j : (i == j) = false
471	    by rewrite gtn_eqF;
472	  rewrite (negbTE Hlti) Hi_ne_j in Hlc Hws;
473	  case Ei1j : (i.-1 == j);
